import{_ as e,o as d,c as s,a2 as a}from"./chunks/framework.BwxVc06z.js";const p=JSON.parse('{"title":"KeyrateGeneral","description":"","frontmatter":{},"headers":[],"relativePath":"tests/keyrate_general.md","filePath":"tests/keyrate_general.md"}'),r={name:"tests/keyrate_general.md"};function o(n,t,l,_,i,c){return d(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="keyrategeneral" tabindex="-1">KeyrateGeneral <a class="header-anchor" href="#keyrategeneral" aria-label="Permalink to &quot;KeyrateGeneral&quot;">​</a></h1><p>The Gaussian de Finetti lift to general attacks, and what it refuses</p><p><strong>14/14 passed</strong> in 5ms</p><table tabindex="0"><thead><tr><th>Test</th><th>What it does</th><th>Result</th></tr></thead><tbody><tr><td><code>test_block_floor_rises</code></td><td>This link distils under a collective attack from about 4e6 symbols and under a general one only between 1.5e7 and 2e7.</td><td>✅ pass</td></tr><tr><td><code>test_certificate_recomputed</code></td><td>K^4 * eps_coll/50 recovers the general-attack target (Eq. (5) inverted) at targets 1e-6 to 1e-20.</td><td>✅ pass</td></tr><tr><td><code>test_cutoff_linear_in_block</code></td><td>K/(n*(d_A + d_B)) stays within 2% of 1 from n = 1e7 to 1e15.</td><td>✅ pass</td></tr><tr><td><code>test_dead_fibre_clamped</code></td><td>A block too short to bound the channel gives length exactly 0 while raw keeps the deficit: at n = 50 raw is minus the toll.</td><td>✅ pass</td></tr><tr><td><code>test_epsilon_pays_the_bill</code></td><td>n * cv_finite at eps_coll/3, less the toll, rebuilds <code>raw</code> exactly.</td><td>✅ pass</td></tr><tr><td><code>test_general_domain</code></td><td>cv_general refuses eps_target outside (0, 1), non-positive k_test, d_a and d_b, and a bad argument shared with cv_finite.</td><td>✅ pass</td></tr><tr><td><code>test_higher_threshold_costs</code></td><td>Raising d_A raises K, shrinks eps_coll and shortens the key.</td><td>✅ pass</td></tr><tr><td><code>test_homodyne_refused</code></td><td>hom = True raises NotImplementedError: Eq. (5) assumes U(n) covariance, the heterodyne no-switching protocol.</td><td>✅ pass</td></tr><tr><td><code>test_lift_costs_key</code></td><td>The general key length is 90.7% of the collective one at n = 1e9, 99.0% at 1e11 and 99.7% at 1e12.</td><td>✅ pass</td></tr><tr><td><code>test_more_test_modes_help</code></td><td>As k_test grows K falls and the key length rises, saturating by 1e8.</td><td>✅ pass</td></tr><tr><td><code>test_thin_sample_bound_insufficient</code></td><td>k_test = 51 clears 2 ln(8/eps_target) but not the bound near 220 at the settled eps ~1e-47 and is refused, while k_test = 1e3 runs.</td><td>✅ pass</td></tr><tr><td><code>test_thin_test_sample_refused</code></td><td>k_test at or below 2 ln(8/eps_target) = 50.2, where no finite cutoff exists, is refused naming that bound.</td><td>✅ pass</td></tr><tr><td><code>test_threshold_below_state_refused</code></td><td>d_a or d_b below the state&#39;s mean photon number, which understates K and lengthens the key, raises naming that value.</td><td>✅ pass</td></tr><tr><td><code>test_toll_is_not_the_cost</code></td><td>The toll ceil(2 log2 C(K+4, 4)) is 248 bits at n = 1e9 and 328 at 1e12, within a bit of 8 log2 K - 2 log2 24, and under 1e-5 of the key length.</td><td>✅ pass</td></tr></tbody></table>',4)])])}const u=e(r,[["render",o]]);export{p as __pageData,u as default};
